// Detailed garden props and three optional ending chains.
function extraFlags(){return flags()}
function yardAction(id){let f=extraFlags();if(id==='seeds')discovery('seeds','The seed packet','Six seeds. The label reads: “For the mornings we never had.” Plant them beside the bench.');if(id==='water')discovery('water','The watering can','Rainwater fills the can. On the handle: “Only water what you want to remember.”');if(id==='plant'){if(!f.seeds||!f.water)return modal('An empty flower bed','Find the seeds and the watering can in the shed first.',[['Back',close]]);discovery('planted','A small act of care','You plant and water the seeds. Pale flowers rise from the soil. If the well has been quieted, the final diary may offer a new morning.')}if(id==='shovel')discovery('shovel','The gardener’s shovel','There is fresh soil on the blade. A brass plate says: “Beside the bench. One hand deep.”');if(id==='dig'){if(!f.shovel)return modal('Disturbed earth','The soil beside the bench is soft. You need a shovel.',[['Back',close]]);discovery('token','The buried locket','Inside is a photograph of Mother holding two identical children. A paper strip reads: “Return this to the roots beside the well.”')}if(id==='bury'){if(!f.token)return modal('The old roots','A hollow between the roots is the shape of a small locket.',[['Back',close]]);discovery('buried','A memory returned','You bury the locket. The tree makes a sound like someone exhaling. This path will wait in the final diary entry.')}if(id==='lantern')discovery('lantern','The storm lantern','You turn its wick. A warm flame catches. Etched on the glass: “The note at the far fence knows the way. Follow a light that casts your own shadow.”')}
const yardTargets=targets;targets=function(){return yardTargets().concat([{name:'Seed packet',p:[-7.4,1.4,-6.2],fn:()=>yardAction('seeds')},{name:'Watering can',p:[-6.7,.3,-6],fn:()=>yardAction('water')},{name:'Flower bed',p:[5.5,.15,-1.7],fn:()=>yardAction('plant')},{name:'Gardener’s shovel',p:[-4.4,1,-8.5],fn:()=>yardAction('shovel')},{name:'Disturbed earth',p:[6.4,.06,-4.2],fn:()=>yardAction('dig')},{name:'Old tree roots',p:[6.4,.25,-7.5],fn:()=>yardAction('bury')},{name:'Storm lantern',p:[-5.4,1.1,-7.8],fn:()=>yardAction('lantern')}])};
const yardSurface=surface;surface=function(t){if(!['Seed packet','Watering can','Flower bed','Gardener’s shovel','Disturbed earth','Old tree roots','Storm lantern'].includes(t.name))return yardSurface(t);let floor=['Flower bed','Disturbed earth','Old tree roots'].includes(t.name);let [x,y,z]=t.p,w=floor?.7:.35,h=t.name==='Gardener’s shovel'?1.4:.45;return floor?[[x-w/2,y,z-w/2],[x+w/2,y,z-w/2],[x+w/2,y,z+w/2],[x-w/2,y,z+w/2]]:quadAt(t.p,w,h,'z')};
const yardBuild=buildHouse;buildHouse=function(){yardBuild();
// Individual weathered paving slabs, lawn variation and small weeds.
for(let z=-.6;z>-9.5;z-=.7)for(let x of [-.35,.35])box(x,.025,z,.62,.026,.61,z< -5?'#827e6d':'#8c8674');for(let i=0;i<85;i++){let x=((i*137)%170)/10-8.5,z=-.5-((i*73)%95)/10;if(Math.abs(x)<1||x< -3.7&&z< -4.5||Math.hypot(x-4,z+6)<1.3)continue;box(x,.006,z,.4,.013,.3,['#44593a','#3b5034','#526046'][i%3]);for(let j=0;j<2;j++)box(x+j*.06,.01,z,.015,.07+(i%3)*.03,.015,'#63704b')}
for(let [x,z] of [[6.4,-7.5],[-2.5,-8],[7,-1]]){cylinder(x,0,z,.19,2.4,'#5f5542');house.solids.push({x,z,w:.38,d:.38,y:0,h:2.4});for(let a of [-.4,.4])foliage(x+a,2.6,z,1,'#3e583a');foliage(x,3.3,z,.9,'#536344')}
for(let z of [-2,-3.5,-5,-8.5])foliage(8.2,.35,z,.48,'#47563a');for(let x of [2,3,4,5,6]){box(x,.05,-1.7,.84,.15,.8,'#483d2b');box(x,.15,-1.7,.75,.02,.7,'#42382d');if(flags().planted)for(let j=0;j<3;j++){box(x+j*.1-.1,.17,-1.7,.02,.24,.02,'#66784c');foliage(x+j*.1-.1,.42,-1.7,.05,'#d8cf9e')}}
// Rain barrel, terracotta pots, porch brickwork and hanging lamp.
cylinder(-3,.02,-3.5,.4,.85,'#635948');house.solids.push({x:-3,z:-3.5,w:.8,d:.8,y:0,h:.85});for(let x of [-2,2]){cylinder(x,0,-.7,.28,.4,'#937350');foliage(x,.65,-.7,.35,'#617250')}box(0,2.4,-.5,2.4,.14,1,'#625c49');box(.9,1.85,-.13,.2,.35,.18,'#ab986a');for(let row=0;row<8;row++)for(let col=0;col<3;col++){let x=-1.4+col*.25;if(x>-.6)continue;box(x,row*.24+.04,-.105,.23,.2,.018,row%2?'#756650':'#887960')}
// Clue props have visible geometry at their interaction points.
box(-7.4,1.25,-6.2,.32,.3,.03,'#bcb089');cylinder(-6.7,.02,-6,.2,.4,'#7e8e81');box(-6.4,.24,-6,.34,.065,.065,'#7e8e81');box(-4.4,.3,-8.5,.04,1.35,.04,'#91734b');box(-4.4,.05,-8.5,.3,.35,.055,'#7e8178');box(6.4,.013,-4.2,.7,.04,.65,flags().token?'#372e25':'#63543c');box(-5.4,.84,-7.8,.22,.12,.22,'#343b2f');box(-5.4,.96,-7.8,.16,.27,.16,flags().lantern?'#d9b56d':'#7a8474');box(-5.4,1.23,-7.8,.24,.08,.24,'#343b2f');
};
function yardEndingAllowed(id){let f=flags();return id==='morning'?f.planted&&f.wellQuiet:id==='burial'?f.buried&&noteState().includes('note4'):id==='light'?f.lantern&&noteState().includes('note5'):false}
const nineEndings=ending;ending=function(id){let data={morning:['Ending X · A garden for tomorrow','At dawn, every flower faces the house. You invite Mother outside.\nShe names the flowers instead of naming the things she lost.\nFor the first time, the diary has no entry for tomorrow.'],burial:['Ending XI · What the earth keeps','You leave the memory beneath the roots. The spare room fills with the smell of rain.\nMother remembers love without remembering the room.\nEvery autumn, you find one small brass leaf beneath the tree.'],light:['Ending XII · Your own shadow','The lantern lights a path beyond the garden. You follow the shadow that moves exactly when you do.\nBehind you, the house keeps calling your name.\nYou let the flame answer.']};if(!data[id])return nineEndings(id);if(!yardEndingAllowed(id))return;s.ending={title:data[id][0],body:data[id][1]};save();showEnding()};
const nineFinale=finale;finale=function(){if(!s.read){diary();return}let ids=['morning','burial','light'].filter(yardEndingAllowed);if(!ids.length)return nineFinale();modal('The garden remembers','Your work outside has revealed more ways to end the story.',[['House and earlier garden paths',nineFinale],...ids.map(id=>[({morning:'Wait for morning in the garden',burial:'Leave the memory beneath the roots',light:'Follow your own shadow'})[id],()=>ending(id)]),['Keep exploring',close]])};
const yardTasks=taskRows;taskRows=function(){return yardTasks().concat(flags().seeds||flags().water?[{label:'Garden: plant and water the seeds',done:!!flags().planted}]:[],flags().shovel?[{label:'Garden: find and bury the locket',done:!!flags().buried}]:[],[{label:'Garden: light the storm lantern',done:!!flags().lantern}])};
const yardChecklist=updateChecklist;updateChecklist=function(){yardChecklist();let label=taskHUD.querySelector('.secret-count');if(label)label.textContent='12 POSSIBLE ENDINGS · '+noteState().length+'/6 NOTES'};
const naturalMovement=updateMovement;house.stepClock=0;updateMovement=function(dt){naturalMovement(dt);let moving=Object.entries(house.keys).some(([k,v])=>v&&['w','a','s','d','arrowup','arrowdown'].includes(k));let old=house.walkBob||0;if(moving&&house.jumpHeight===0){house.stepClock+=dt*(house.sprinting?11:7);house.walkBob=Math.sin(house.stepClock)*.014}else house.walkBob=old*Math.max(0,1-dt*14);if(Math.abs(old-house.walkBob)>.0001)house.dirty=true};
const oldResetBob=reset;reset=function(){house.walkBob=0;house.stepClock=0;oldResetBob()};
render();
